from __future__ import annotations; from pathlib import Path; from typing import Any; import yaml; from common.testing import evidence_bundle as eb; from common.testing.ac_proof_execution import PROOF_EXECUTION_STAGES, PROOF_TASK_CATEGORIES; ROOT = Path(__file__).resolve().parents[2]; RETIRED_INVENTORY = ROOT / 'common' / 'meta' / 'data' / 'ci-gate-inventory.yaml'; WORKFLOWS = ROOT / '.github' / 'workflows'; EXPECTED_STAGES = set(PROOF_EXECUTION_STAGES); EXPECTED_TASK_CATEGORIES = set(PROOF_TASK_CATEGORIES)
def _load_yaml(path: Path) -> dict[str, Any]: data = yaml.safe_load(path.read_text(encoding='utf-8')); assert isinstance(data, dict), path; return data
def _workflow_jobs() -> set[tuple[str, str]]:
    jobs: set[tuple[str, str]] = set()
    for workflow in sorted(WORKFLOWS.glob('*.yml')): data = _load_yaml(workflow); [jobs.add((f'.github/workflows/{workflow.name}', str(job_id))) for job_id in data.get('jobs') or {}]
    return jobs
def _job_run_commands(workflow: dict[str, Any], job_id: str) -> str: job = workflow['jobs'][job_id]; return '\n'.join((str(step.get('run', '')) for step in job.get('steps', []) if isinstance(step, dict)))
